// The kobold's tools in an exploration's conversation, served over MCP (the
// standard way to give Claude new actions): it looks at the board, adds
// notes, diagrams and choices, changes and removes things, links and
// unlinks them with a short label, points at a thing (the person's view
// moves there), marks a thing agreed or a sketch, and starts making an
// option's prototype. Each answers with
// what it did and the whole board. Beside them, the made-up world's tools
// (world-tools.ts). Only the conversation's own Claude Code
// has the token.
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { COACH_HEADER } from "../../coach/setup-tools.js";
import { answerMcp, toolAnswer } from "../../mcp.js";
import { addWorldTools } from "./world-tools.js";
const option = z.object({
    key: z
        .string()
        .optional()
        .describe("An option to change (A, B…); none: a new one."),
    name: z.string().optional().describe("A few words."),
    difference: z.string().optional().describe("How it differs, in one line."),
});
const TOOLS = [
    {
        name: "add_note",
        description: "A short note: something the team said or decided, a line or two.",
        input: { text: z.string().min(1) },
        act: (a) => ({ act: "note", text: String(a.text) }),
    },
    {
        name: "add_diagram",
        description: "A simple Mermaid flowchart in plain words (the steps of a journey, who talks to whom, the stages something goes through); at most a dozen boxes, no developer words.",
        input: { title: z.string().min(1), diagram: z.string().min(1) },
        act: (a) => ({
            act: "diagram",
            title: String(a.title),
            diagram: String(a.diagram),
        }),
    },
    {
        name: "add_choice",
        description: "A real choice: the question that has to be decided and its options (A, B, C), each a few words with a one-line difference.",
        input: { title: z.string().min(1), options: z.array(option) },
        act: (a) => ({
            act: "choice",
            title: String(a.title),
            options: a.options,
        }),
    },
    {
        name: "change_thing",
        description: "Change a thing by its id: a note's text, a title, a diagram, a choice's options (change by letter, add without one, removeOptions by letter).",
        input: {
            id: z.string(),
            text: z.string().optional(),
            title: z.string().optional(),
            diagram: z.string().optional(),
            options: z.array(option).optional(),
            removeOptions: z.array(z.string()).optional(),
        },
        act: (a) => ({ act: "change", ...a }),
    },
    {
        name: "remove_thing",
        description: "Take a thing off the board, with its arrows.",
        input: { id: z.string() },
        act: (a) => ({ act: "remove", id: String(a.id) }),
    },
    {
        name: "link",
        description: "An arrow from one thing to another, with a short label (a word or two).",
        input: { from: z.string(), to: z.string(), label: z.string().optional() },
        act: (a) => ({
            act: "link",
            from: String(a.from),
            to: String(a.to),
            label: typeof a.label === "string" ? a.label : "",
        }),
    },
    {
        name: "unlink",
        description: "Take an arrow off.",
        input: { from: z.string(), to: z.string() },
        act: (a) => ({ act: "unlink", from: String(a.from), to: String(a.to) }),
    },
    {
        name: "agree",
        description: "Mark a thing agreed (talked through and agreed with the team) or a sketch again. One prototype at most is agreed.",
        input: { id: z.string(), agreed: z.boolean() },
        act: (a) => ({ act: "agree", id: String(a.id), agreed: a.agreed === true }),
    },
];
function serverFor(on) {
    const server = new McpServer({ name: "board", version: "1.0.0" });
    for (const tool of TOOLS)
        server.registerTool(tool.name, { description: tool.description, inputSchema: tool.input }, (args) => toolAnswer(() => on.act(tool.act(args))));
    server.registerTool("look_at_board", {
        description: "The whole board: its things with their ids, and the arrows.",
    }, () => toolAnswer(() => on.look()));
    server.registerTool("point_at", {
        description: "Point at a thing while you talk about it: the person's view moves there.",
        inputSchema: { id: z.string() },
    }, (args) => toolAnswer(() => on.point(args.id)));
    server.registerTool("name_exploration", {
        description: "The exploration's title (a few words) or its problem (two or three sentences).",
        inputSchema: {
            title: z.string().optional(),
            problem: z.string().optional(),
        },
    }, (args) => toolAnswer(() => on.rename(args)));
    addPrototypeTools(server, on);
    addWorldTools(server, on.world.worlds, on.world.id);
    return server;
}
// Making a choice's option's prototype, and changing one.
function addPrototypeTools(server, on) {
    server.registerTool("make_prototype", {
        description: "Start making the prototype of one option of a choice: it appears on the board at once and is made in the background (a few minutes), in its own copy of the code. Make one when trying it will teach more than talking (the team picked the option, or asked for it, or it settles the question); say in one line what you started.",
        inputSchema: {
            choice: z.string().describe("The choice's id (choice-1)."),
            option: z.string().describe("The option's letter (A, B …)."),
        },
    }, (args) => toolAnswer(() => on.make(args.choice, args.option)));
    server.registerTool("change_prototype", {
        description: "Change a prototype that is already on the board, as the team asks (what it shows, where a button leads, what a page says): the maker changes it in its copy, a new version on its branch, in a few minutes; the board shows it being made, then running again. Use it whenever the team wants a prototype different; a note does not change it. Say in one line what you started.",
        inputSchema: {
            prototype: z.string().describe("The prototype's letter (A, A2 …)."),
            change: z
                .string()
                .min(1)
                .describe("What to change, in the team's words, complete."),
        },
    }, (args) => toolAnswer(() => on.change(args.prototype, args.change)));
}
export async function answerBoardTools(incoming, response, on, body) {
    if (incoming.headers[COACH_HEADER] !== on.token) {
        response.writeHead(403, { "content-type": "application/json" });
        response.end(JSON.stringify({ error: "Only this exploration's kobold." }));
        return;
    }
    await answerMcp(incoming, response, serverFor(on), body);
}
